    LANGUAGE_WRAPPER = 'Let a be a real number with \\(\\cos a \\notin \\{0,\\pm\\tfrac{1}{2}\\}\\), and let \\(b,c,d\\) be positive real numbers. For fixed integers \\(p,q\\) with \\(1\\le p<q\\), determine the maximum value of\n\\[\n\\frac{16(\\cos a)^5-\\cos(5a)}{2\\cos a+\\cos(3a)}\\cdot\\frac{a^{p}b^{q}+b^{p}c^{q}+c^{p}d^{q}}{a^{p+q}+b^{p+q}+c^{p+q}+d^{p+q}}.\n\\]\nAfter solving, please output your final answer in the format:\n### The final answer is: $\\boxed{<your answer>}$\nusing standard mathematical notation.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose p and q with 1 <= p < q, and keep them modest to avoid unwieldy outputs.
# Ensure nontrivial difficulty by avoiding q = p+1 only occasionally.
for _ in range(100):
    p = rng.randint(1, 5)
    q = rng.randint(p+1, p+5)
    # Reject trivial or degenerate choices that could overly simplify the constant
    if p >= 1 and q > p and q <= 10 and (p, q) != (1, 2):
        return {'p': p, 'q': q}
# Fallback if randomization fails
return {'p': 2, 'q': 5}

    def verifier(assign):
# Validate domain constraints and compute the exact maximal value.
# The trigonometric factor simplifies identically to 5 for all allowed a:
# 16 cos^5 a - cos(5a) = 5(2 cos a + cos(3a)), so the ratio is 5.
# The remaining optimization is:
# maximize F = (a^p b^q + b^p c^q + c^p d^q) / (a^{p+q} + b^{p+q} + c^{p+q} + d^{p+q}).
# Setting A=a^{p+q}, B=b^{p+q}, C=c^{p+q}, D=d^{p+q} and \lambda=p/(p+q),
# the numerator becomes A^\lambda B^{1-\lambda} + B^\lambda C^{1-\lambda} + C^\lambda D^{1-\lambda}.
# Using Lagrange multipliers, the optimal shape is a geometric progression with ratio r = q/p for (A,B,C,D).
# With A = 1/(1+r+r^2+r^3), the maximum equals r^{1-\lambda} (1+r+r^2) / ((1+r)(1+r^2)).
# Thus the overall maximum is 5 times that quantity.
p = assign.get('p', None)
q = assign.get('q', None)
# Basic validations
if not isinstance(p, int) or not isinstance(q, int):
    # invalid types
    return (False, None)
if p < 1 or q <= p:
    # domain constraints violated
    return (False, None)
# Compute symbolic closed form: 5 * ( (q/p)^{q/(p+q)} ) * (p^2 + p q + q^2) / ( (p+q)(p^2 + q^2) )
# This is exact and derived from r = q/p and simplification of (1+r+r^2)/((1+r)(1+r^2)).
from math import log, exp
# Build LaTeX string for the answer.
# We keep it exact in terms of p and q with a rational prefactor and a power term.
# numerical check (optional for difficulty enforcement): ensure value is not trivially 5.
pref_num = p*p + p*q + q*q
pref_den = (p+q)*(p*p + q*q)
# The exponential factor (q/p)^{q/(p+q)}
# We'll compose the LaTeX string rather than computing a float to avoid precision loss.
# Verify nontriviality: the prefactor should be strictly between 0 and 1 for p<q.
if not (0 < pref_num < pref_den):
    # If this fails, something degenerate happened
    return (False, None)
# Assemble LaTeX expression
answer = f"### The final answer is: $\\boxed{{5 \\cdot \\frac{{{pref_num}}}{{{pref_den}}} \\cdot \\left(\\frac{{{q}}}{{{p}}}\\right)^{{\\frac{{{q}}}{{{p}+{q}}}}}}}$"
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
